export const THANE_CREEK_DATA={id:"thane-creek-wetland-explorer",name:"Thane Creek Wetland Explorer",subtitle:'Mumbai\'s First Ramsar Site & the "Sea of Pink" Flamingo Sanctuary',location:"Between Mumbai, Navi Mumbai & Thane, Maharashtra",ramsarSiteNo:2472,ramsarDeclared:2022,area:"6,522.5 ha (Sanctuary + Eco-Sensitive Zone) / 1,690.5 ha Core Sanctuary",type:"Estuarine Mangrove Creek & Tidal Mudflat Wetland",coordinates:{lat:19.08,lng:72.98},stats:[{label:"Core Sanctuary Area",value:"1,690.5 ha",icon:"🌊"},{label:"Migratory Birds (Winter)",value:"1,00,000+",icon:"🦩"},{label:"Ramsar Declared",value:"2022",icon:"🪷"},{label:"Eco-Sensitive Zone",value:"4,832 ha",icon:"🌿"}],history:{title:"From Industrial Backwater to Protected Wetland",content:"For decades, Thane Creek sat quietly between Mumbai, Navi Mumbai, and Thane, hemmed in by refineries, railway lines, and expanding suburbs. Conservationists and citizen groups spent years documenting its mangroves and bird life, pushing the state to recognise the creek as more than reclaimable land. In August 2015, the Maharashtra Government notified the northern stretch of the creek as the Thane Creek Flamingo Sanctuary, the state's second marine sanctuary after Malvan. That protection, combined with sustained advocacy from the Mangrove Cell and local naturalists, laid the groundwork for the wetland's international recognition seven years later."},ramsarSite:{title:"Mumbai's First Ramsar Site",content:"On 13 August 2022, the Thane Creek Flamingo Sanctuary became Mumbai's first Ramsar-designated Wetland of International Importance, part of a batch of eleven new Indian wetlands recognised that year. The designation covers 1,690.5 hectares of core sanctuary, made up of mangrove forest and tidal creek, surrounded by a much larger 4,832-hectare Eco-Sensitive Zone that buffers the wetland from the dense city around it. The Ramsar Convention itself is a 1971 international treaty, named after the Iranian city where it was signed, that commits member countries to conserving wetlands of global ecological value."},mangroveEcosystem:{title:"A Mangrove Forest in the Middle of a Megacity",content:'Roughly 896 hectares of the sanctuary are dense mangrove forest, threaded through with tidal creeks and mudflats that flood and drain with every tide. Species such as Avicennia marina and Sonneratia line the creek banks, trapping silt, buffering the coastline from storm surge, and filtering pollutants before they reach the Arabian Sea. Because it sits wedged between three of India\'s most crowded urban areas, the creek is often described as one of the "lungs" of the Mumbai metropolitan region, absorbing carbon and easing the urban heat load even as skyscrapers rise along its edges.'},flamingos:{title:"The Sea of Pink",subtitle:"Every winter, tens of thousands of flamingos turn the creek into a shifting pink horizon.",content:"Thane Creek hosts two species of flamingo: the taller, paler Greater Flamingo and the smaller, more vividly coloured Lesser Flamingo. Neither bird is born pink — chicks hatch grey and white, and their signature blush comes later, built up from carotenoid pigments in the algae, plankton, and small crustaceans they filter from the mudflats. The birds arrive from breeding grounds across India and Central Asia each winter, and the sanctuary's boat safaris, run exclusively by the Mangrove Cell of the Maharashtra Forest Department, are the main way visitors get close to the flocks without disturbing them.",facts:["The sanctuary's flamingos are part of the Central Asian Flyway, a migratory corridor spanning dozens of countries.","Boat safari slots are tide-dependent and limited, so tickets are in high demand during peak flamingo season.","Greater and Lesser Flamingos often feed side by side, giving the mudflats a mixed palette of pale and deep pink."]},marineBiodiversity:{title:"Beyond the Flamingos: A Living Estuary",content:"The creek's brackish water and mangrove roots shelter far more than flamingos. Fiddler crabs, mudskippers, and shellfish work the exposed mudflats at low tide, while herons, egrets, sandpipers, and other wading birds share the shoreline with the flamingo flocks. Juvenile fish and prawns use the tangled mangrove roots as a nursery before moving out toward the open sea, making the creek an important breeding ground for species that later support commercial fisheries along the Konkan coast."},conservation:{title:"Conservation Under Pressure",content:"Thane Creek's location inside one of India's largest urban agglomerations makes it a rare case of a Ramsar site fighting for survival street by street. A Management Plan for the period 2020–2030, prepared by the Mumbai Mangrove Conservation Unit, sets out goals for flamingo and mangrove protection, eco-tourism, and community education. Even so, encroachment, waste dumping, and pollution from surrounding wetlands remain live concerns; in 2026, the central government directed Maharashtra's wetland authority to act after activists flagged deteriorating water quality in marshes linked to the sanctuary. Continued protection depends on strict enforcement of the Wetlands (Conservation and Management) Rules and on keeping development out of the buffer zone."},hotspots:[{id:"airoli-jetty",name:"Airoli Flamingo Jetty",lat:19.16,lng:72.99,desc:"Main boat safari departure point into the northern mudflats and mangrove channels."},{id:"vashi-bridge",name:"Vashi Creek Bridge Viewpoint",lat:19.08,lng:72.99,desc:"Elevated view over the creek where flocks gather at low tide, roughly midway along the sanctuary."},{id:"twf-centre",name:"Thane Creek Flamingo & Wetlands Interpretation Centre",lat:19.15,lng:72.99,desc:"Visitor centre with exhibits on mangrove ecology, sanctuary history, and bird identification."},{id:"nerul-mudflats",name:"Nerul Mudflats",lat:19.03,lng:73.02,desc:"Southern feeding grounds important to wading birds, and an area under active conservation monitoring."}],gallery:[{title:"Flamingos at Thane Creek",url:"https://commons.wikimedia.org/wiki/Special:FilePath/Thane%20creek%20Flamingo%20Scantuary.jpg",caption:"Greater and Lesser Flamingos feeding in the sanctuary."},{title:"Lesser and Greater Flamingos",url:"https://commons.wikimedia.org/wiki/Special:FilePath/Lesser%20and%20Greater%20Flamingos%20at%20Thane%20Creek%20by%20Dr.%20Raju%20Kasambe%20%282%29.jpg",caption:"Both flamingo species together at Thane Creek."},{title:"Thousands of Lesser Flamingos",url:"https://commons.wikimedia.org/wiki/Special:FilePath/Lesser%20Flamingos%20Phoeniconaias%20minor%20congregation%20Thane%20Creek%20by%20Raju%20Kasambe%2007.jpg",caption:"Large congregation of Lesser Flamingos."},{title:"Flamingo Congregation",url:"https://commons.wikimedia.org/wiki/Special:FilePath/Lesser%20Flamingos%20Phoeniconaias%20minor%20congregation%20Thane%20Creek%20by%20Raju%20Kasambe%2001.jpg",caption:"A panoramic view of thousands of flamingos."}],facts:["Thane Creek Flamingo Sanctuary is Mumbai's first Ramsar-recognised Wetland of International Importance.","A flamingo's pink colour comes entirely from its diet — chicks are born grey and white.","The sanctuary sits between three major urban centres, making it one of the few Ramsar sites embedded inside a megacity.","Boat safaris into the sanctuary are run only by the Maharashtra Forest Department's Mangrove Cell, and tide timing decides when trips can run."]};